CREATE TABLE app_roles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(40) NOT NULL UNIQUE CHECK (name IN ('ADMIN','INVENTORY_MANAGER','SALES_STAFF','PURCHASE_MANAGER')));
CREATE TABLE app_users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(120) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_roles (user_id BIGINT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, role_id BIGINT NOT NULL REFERENCES app_roles(id) ON DELETE RESTRICT, PRIMARY KEY (user_id,role_id));
CREATE TABLE categories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(500));
CREATE TABLE subcategories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_id BIGINT NOT NULL REFERENCES categories(id) ON DELETE RESTRICT, name VARCHAR(100) NOT NULL, UNIQUE (category_id,name), UNIQUE (category_id,id));
CREATE TABLE brands (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE suppliers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(254) UNIQUE, phone VARCHAR(30), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE customers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(254) UNIQUE, phone VARCHAR(30));
CREATE TABLE warehouses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sku VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, description TEXT, category_id BIGINT NOT NULL REFERENCES categories(id) ON DELETE RESTRICT, subcategory_id BIGINT, brand_id BIGINT REFERENCES brands(id) ON DELETE RESTRICT, unit_price NUMERIC(12,2) NOT NULL CHECK (unit_price >= 0), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (category_id,subcategory_id) REFERENCES subcategories(category_id,id));
CREATE TABLE inventory (warehouse_id BIGINT NOT NULL REFERENCES warehouses(id) ON DELETE RESTRICT, product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE RESTRICT, quantity_on_hand INTEGER NOT NULL DEFAULT 0 CHECK (quantity_on_hand >= 0), reorder_level INTEGER NOT NULL DEFAULT 0 CHECK (reorder_level >= 0), updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (warehouse_id,product_id));
CREATE INDEX idx_products_name ON products(name); CREATE INDEX idx_products_category ON products(category_id); CREATE INDEX idx_inventory_product ON inventory(product_id); CREATE INDEX idx_suppliers_name ON suppliers(name);
INSERT INTO app_roles(name) VALUES ('ADMIN'),('INVENTORY_MANAGER'),('SALES_STAFF'),('PURCHASE_MANAGER');

